def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n >= 99:
        return 'D'

    last_my, last_opp = history[-1]

    opp_d = 0
    for _, o in history:
        if o == 'D':
            opp_d += 1
    opp_c = n - opp_d

    recent10 = history[-10:] if n >= 10 else history
    recent10_d = 0
    for _, o in recent10:
        if o == 'D':
            recent10_d += 1

    d_streak = 0
    for _, o in reversed(history):
        if o == 'D':
            d_streak += 1
        else:
            break

    c_after_d = 0
    d_after_d = 0
    for i in range(1, n):
        if history[i - 1][0] == 'D':
            if history[i][1] == 'C':
                c_after_d += 1
            else:
                d_after_d += 1

    defector = (
        (d_streak >= 5 and c_after_d == 0)
        or recent10_d >= 7
        or opp_d > opp_c + 8
    )
    if defector:
        return 'D'

    if c_after_d > d_after_d and c_after_d >= 2 and opp_c > opp_d and recent10_d <= 5:
        return 'D'

    if c_after_d >= 1 and d_after_d == 0 and opp_c * 10 >= n * 7 and recent10_d <= 1:
        return 'D'

    if last_opp == 'C':
        if recent10_d <= 1 and c_after_d >= 1 and d_after_d <= 1 and n >= 30 and opp_c * 10 >= n * 7:
            return 'D'

        if n == 12 and opp_d == 0 and last_my == 'C':
            return 'D'

        if n >= 96 and c_after_d + d_after_d >= 2 and c_after_d >= d_after_d and recent10_d <= 2:
            return 'D'

        return 'C'

    if last_my == 'D' or (n >= 2 and history[-2][0] == 'D'):
        return 'C'

    if d_streak >= 2 and opp_c > opp_d and recent10_d <= 5:
        return 'C'

    if n >= 93 and opp_c > opp_d and recent10_d <= 5:
        return 'C'

    return 'D'
